(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18+Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*18+Math.sin(x*0.016+t*0.3)*12;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.025-t*0.4)*8+Math.cos(my*0.02+t*0.35)*6;
  const w2y = Math.cos(my*0.022+t*0.45)*8+Math.sin(mx*0.018-t*0.3)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*55, 0.07, 2.2, 1.0],
    [320+Math.cos(t*0.45)*110, 160+Math.sin(t*0.6)*55, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.45+1)*95, 0.055, 2.5, 1.1],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.5+3)*65, 0.11, 1.6, 0.85],
    [380+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.8+2)*75, 0.065, 2.8, 1.05],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.5)*85, 0.08, 2.0, 0.95],
    [60+Math.sin(t*0.55+3)*70, 120+Math.cos(t*0.65+4)*90, 0.1, 1.9, 0.88],
    [420+Math.cos(t*0.42+2)*60, 140+Math.sin(t*0.48+1)*80, 0.075, 2.4, 1.02]
  ];
  let aS=0, iS=0, fS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.55+1.5)*w;
    fS += Math.sin(d*f*1.4-t*sp*0.8+3.0)*w*0.5;
  }
  const act=aS/8, inh=iS/8, feed=fS/8;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*1.0)+Math.sin(sx*0.05+sy*0.01-t*0.9))/3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.045-ang*3.5-t*1.4), sp2=Math.sin(dist*0.035+ang*5-t*1.1);
  const sp3=Math.sin(dist*0.06-ang*2+t*1.8)*0.5;
  const spiral=(sp1+sp2+sp3)*0.33;
  const turb=Math.sin(sx*0.08+Math.sin(sy*0.06+t*0.5)*2+t)*0.3+Math.sin(sy*0.07+Math.sin(sx*0.05-t*0.4)*2-t)*0.3;
  const lap = Math.sin(sx*0.12)*Math.sin(sy*0.12)+Math.sin((sx+sy)*0.08+t*0.7)*0.5+Math.sin((sx-sy)*0.09-t*0.5)*0.4;
  const rd = Math.tanh((act - inh*0.65 + feed*0.4 + bg*0.25 + spiral*0.35 + turb*0.15)*2.0);
  const cell = Math.tanh(lap*1.8)*0.35;
  const glow = Math.exp(-dist*0.008)*Math.sin(t*0.8)*0.15;
  const pulse = Math.sin(dist*0.03-t*2.0)*Math.exp(-dist*0.005)*0.2;
  const blend = rd*0.6+cell*0.2+glow+pulse, v=blend*0.5+0.5;
  const pal = [[5,10,45],[10,35,85],[18,75,120],[25,130,130],[45,175,145],[140,195,120],[210,185,75],[220,145,55],[195,90,60],[160,50,65],[100,25,55],[40,12,42],[5,10,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(rd*Math.PI)*0.18;
  const edge=Math.abs(rd)>0.65?1.12:Math.abs(rd)>0.3?1.04:1.0;
  const vig=1.0-Math.pow(dist/300,2)*0.25;
  const m=lum*edge*vig;
  return [
    Math.min(255,Math.max(0,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m))|0,
    Math.min(255,Math.max(0,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m))|0,
    Math.min(255,Math.max(0,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m))|0
  ];
}
